UPDATE public.quizzes SET questions = questions || '[{"article": "Le contrat de travail à durée indéterminée peut comporter une période d''essai dont la durée maximale est de : 1° Deux mois pour les ouvriers et les employés ; 2° Trois mois pour les agents de maîtrise et les techniciens ; 3° Quatre mois pour les cadres.", "casus": "[Dossier 2] Un cadre est recruté en CDI. Son contrat mentionne une période d''essai.", "correct_index": 0, "id": 2, "options": ["4 mois", "3 mois", "2 mois", "6 mois"], "question": "Dossier n°2 : Quelle est la durée maximale initiale de la période d''essai pour un cadre ?", "reference": "Art. L1221-19"}]'::jsonb WHERE id = 8;
